import { cn } from '@/lib/utils';
import React from 'react';
import { Link } from 'react-router-dom';

interface IconProps {
    num?: number | string;
    text?: string;
    icon?: React.ReactNode;
    percent?: number;
    className?: string;
    label?: string;
    negative?: boolean;
    numJustifyStart?: boolean;
    to?: string;
}

const cardClassName =
    'relative bg-[#E8EFF666] ps-6 pe-4 pt-4 pb-5 shadow-[0px_2px_12px_0px_#14142B14] rounded-[8px] flex flex-row items-start justify-between gap-4 border border-solid border-primery-blue-100 min-h-[120px]';

const StatisticsCard = ({
    num,
    text,
    icon,
    percent,
    className = '',
    label,
    negative = false,
    numJustifyStart = false,
    to,
}: IconProps) => {
    const content = (
        <>
            <div className="flex flex-1 flex-col min-w-0">
                <div className="flex flex-row items-center justify-between gap-2">
                    {num !== undefined && (
                        <div
                            className={cn(
                                'flex flex-row items-center gap-[6px] text-[32px] leading-[48px] text-primery-blue-900 font-bold tracking-normal shrink-0',
                                { 'justify-start': label || numJustifyStart },
                            )}
                        >
                            {num}
                            {label && (
                                <div className="leading-[24px] text-base text-primery-blue-900 font-medium tracking-normal">
                                    {label}
                                </div>
                            )}
                        </div>
                    )}
                    {icon && (
                        <div className="rounded-full bg-primery-blue-100 w-14 h-14 flex items-center justify-center shrink-0">
                            {icon}
                        </div>
                    )}
                </div>
                {text && (
                    <div className="mt-auto pt-1 text-nowrap min-w-[73px] font-semibold w-fit pb-[10.5px] text-4 text-primery-blue-500 leading-[20px] tracking-normal border-b border-primery-blue-500">
                        {text}
                    </div>
                )}
            </div>
            {percent !== undefined && (
                <div
                    dir="ltr"
                    className={cn(
                        'absolute bottom-0 left-0 text-[#ffffff] text-xs leading-[13.8px] font-normal tracking-normal flex items-center justify-center w-[53px] h-[22px] py-1 px-4 rounded-tl-[4px] rounded-tr-[4px] rounded-bl-[8px]',
                        { 'bg-[#F59E0B]': percent === 0 },
                        { 'bg-[#F23030]': percent < 0 && !negative },
                        { 'bg-[#22AD5C]': percent > 0 && !negative },
                        { 'bg-[#F23030]': percent > 0 && negative },
                    )}
                >
                    {percent}
                    <span>%</span>
                </div>
            )}
        </>
    );

    if (to) {
        return (
            <Link to={to} className={cn(cardClassName, className, 'block cursor-pointer hover:opacity-90 transition-opacity')}>
                {content}
            </Link>
        );
    }

    return <div className={cn(cardClassName, className)}>{content}</div>;
};

export default StatisticsCard;
